import java.util.*;

public class Main {
    public static void main(String[] args) {
        DriveService drive = new DriveService();

        // Upload file "doc1" version 1 with 3 chunks.
        drive.uploadVersion("doc1", "v1", null, Arrays.asList("chunk-hello", "chunk-world", "chunk-end"));
        System.out.println("Unique chunks stored after v1: " + drive.uniqueChunkCount());

        // Upload "doc1" version 2: only the middle chunk actually changed; the other two are reused.
        drive.uploadVersion("doc1", "v2", "v1", Arrays.asList("chunk-hello", "chunk-world-EDITED", "chunk-end"));
        System.out.println("Unique chunks stored after v2 (only 1 new chunk, not 3): " + drive.uniqueChunkCount());

        // A completely different file, "doc2", happens to share "chunk-hello" (e.g. a common header).
        drive.uploadVersion("doc2", "v1", null, Arrays.asList("chunk-hello", "chunk-doc2-body"));
        System.out.println("Unique chunks stored after doc2 (chunk-hello deduplicated again): " + drive.uniqueChunkCount());

        // Conflict scenario: doc1's canonical version is currently "v2" (from the upload above).
        // Both devices go offline while "v2" is still canonical, and each edits it independently.
        // Device A syncs its edit first: since it was based on the still-current canonical "v2", it succeeds.
        SyncResult resultA = drive.syncEdit("doc1", "deviceA", "v2", "v2-from-A");
        System.out.println("Device A syncs from v2: " + resultA);

        // Device B, still believing v2 is canonical, syncs its own, different edit based on v2.
        // v2 is no longer canonical (v2-from-A is, from A's sync above), so this is a genuine conflict.
        SyncResult resultB = drive.syncEdit("doc1", "deviceB", "v2", "v2-from-B");
        System.out.println("Device B syncs from v2 (now stale): " + resultB);

        System.out.println("doc1's canonical version (should be A's edit): " + drive.canonicalVersion("doc1"));
    }
}

// The outcome of a sync attempt: whether it became the new canonical
// version, or was preserved as a separate conflict copy instead.
class SyncResult {
    String status;
    String resultingVersionOrCopyId;

    SyncResult(String status, String resultingVersionOrCopyId) {
        this.status = status;
        this.resultingVersionOrCopyId = resultingVersionOrCopyId;
    }

    public String toString() {
        return status + " (" + resultingVersionOrCopyId + ")";
    }
}

// Manages content-addressable chunk deduplication and canonical-version
// tracking per file, detecting a genuinely divergent offline edit and
// preserving it as a separate conflict copy rather than overwriting.
class DriveService {
    private final Set<String> uniqueChunks = new HashSet<>();                     // every distinct chunk ever stored, by content id
    private final Map<String, String> canonicalVersionByFile = new HashMap<>();       // fileId -> current canonical version id

    // Uploads a version, deduplicating against already-stored chunks; only
    // genuinely new chunk content actually adds to storage.
    void uploadVersion(String fileId, String versionId, String basedOnVersionId, List<String> chunkContents) {
        for (String chunk : chunkContents) {
            uniqueChunks.add(chunk); // a set naturally deduplicates: adding an already-present chunk is a no-op
        }
        canonicalVersionByFile.put(fileId, versionId); // a normal upload always becomes canonical directly
    }

    int uniqueChunkCount() {
        return uniqueChunks.size();
    }

    // Attempts to sync an edit that was based on basedOnVersionId. If that is
    // still the file's current canonical version, the edit becomes canonical.
    // If the canonical version has since changed (a genuine divergence), the
    // edit is preserved as a separate conflict copy instead.
    SyncResult syncEdit(String fileId, String deviceId, String basedOnVersionId, String newVersionId) {
        String currentCanonical = canonicalVersionByFile.get(fileId);
        if (basedOnVersionId.equals(currentCanonical)) {
            canonicalVersionByFile.put(fileId, newVersionId);
            return new SyncResult("SYNCED_AS_CANONICAL", newVersionId);
        } else {
            String conflictCopyId = fileId + "-conflict-" + deviceId;
            return new SyncResult("CONFLICT_COPY_CREATED", conflictCopyId);
        }
    }

    String canonicalVersion(String fileId) {
        return canonicalVersionByFile.get(fileId);
    }
}

